cat > /tmp/pi-warncheck.mjs <<'EOF'
const base = "/Users/ekassinghchhabra/.pi/agent/install/releases/1.3.0/node_modules/@earendil-works/pi-coding-agent/dist";
const { DefaultResourceLoader } = await import(`${base}/core/resource-loader.js`);
const { builtInExtensions } = await import(`${base}/extensions/index.js`);

const loader = new DefaultResourceLoader({
  cwd: process.cwd(),
  agentDir: "/Users/ekassinghchhabra/.pi/agent",
  extensionFactories: builtInExtensions,
});
await loader.reload({});
const res = loader.getExtensions();
console.log("WARNINGS:");
for (const w of res.warnings ?? []) console.log(" -", w.path, "::", w.warning);
console.log("ERRORS:");
for (const e of res.errors ?? []) console.log(" -", e.path, "::", e.error);
console.log("loaded extensions:", (res.extensions ?? []).map(e => e.path ?? e.name));
EOF
cd ~ && timeout 180 node /tmp/pi-warncheck.mjs 2>&1 | tail -40

